class Solution:
    def minimumSum(self, nums):
        n = len(nums)
        suf = [0] * n
        m = float('inf')
        for i in range(n - 1, -1, -1):
            suf[i] = m
            m = min(m, nums[i])
        pre = nums[0]
        best = float('inf')
        for j in range(1, n - 1):
            if nums[j] > pre and nums[j] > suf[j]:
                best = min(best, pre + nums[j] + suf[j])
            pre = min(pre, nums[j])
        return best if best < float('inf') else -1

